<?php
declare(strict_types=1);
function dossier_export_package(array $v):never{
 $d=dossier_data(dossier_row(field($v,'id',36,true)),false);$ids=$v['entryIds']??array_column($d['entries'],'id');if(!is_array($ids)||count($ids)>50||array_filter($ids,fn($id)=>!is_string($id)))problem('Bitte die Dossierauswahl prüfen.');
 if(array_diff($ids,array_column($d['entries'],'id')))problem('Ein ausgewählter Eintrag gehört nicht zu diesem Dossier.');$d['entries']=array_values(array_filter($d['entries'],fn($e)=>in_array($e['id'],$ids,true)));if(!$d['entries'])problem('Bitte mindestens einen Eintrag wählen.');
 $md='# '.$d['title']."\n\n".($d['intro']??'')."\n\n";$html='<h1>'.htmlspecialchars($d['title'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</h1><pre>'.htmlspecialchars($d['intro']??'',ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</pre>';$size=0;$files=[];
 foreach($d['entries'] as &$entry){if(!$entry['available']){$md.="Quelle nicht mehr verfügbar.\n\n";continue;}$s=$entry['source'];$citation=newspaper_citation($s['newspaper']??[]);$text=$entry['kind']==='quote'?$entry['quote']:(string)(sql('SELECT content FROM clips WHERE id=? AND '.active_clip_condition('clips'),[$entry['clipId']])->fetchColumn()?:'');if($entry['kind']==='document'&&$s['type']==='pdf'){$prefix=pdf_index_prefix(pdf_metadata(sql('SELECT archive_key FROM clips WHERE id=?',[$entry['clipId']])->fetchColumn()?:''));if(str_starts_with($text,$prefix))$text=substr($text,strlen($prefix));}
  if($entry['kind']==='document'&&$s['type']==='pdf'&&!empty($entry['page'])){$blocks=preg_split('/(?:^|\n)Seite (\d+)\n/u',$text,-1,PREG_SPLIT_DELIM_CAPTURE);$selected='';for($i=1;$i<count($blocks);$i+=2)if((int)$blocks[$i]===(int)$entry['page'])$selected.='Seite '.$blocks[$i]."\n".($blocks[$i+1]??'')."\n";$text=trim($selected);}
  if(($v['includeArticlePdfs']??false)===true&&$entry['kind']==='document'&&!empty($s['newspaper']['hasPdf'])){$key=sql('SELECT archive_key FROM clips WHERE id=?',[$entry['clipId']])->fetchColumn();if($key&&str_ends_with($key,'.pdf')&&is_file(archive_path($key))){$name='artikel/'.preg_replace('/[^a-zA-Z0-9-]/','_',$entry['clipId']).'.pdf';$files[$name]=archive_path($key);$entry['articlePdf']=$name;$size+=filesize(archive_path($key));}}
  $entry['exportText']=$text;$size+=strlen($text);if($size>25*1024*1024)problem('Dieses Dossier ist zu groß. Bitte weniger Einträge exportieren.');$heading=$s['title'].($entry['page']?' · PDF-Seite '.$entry['page']:'');$md.='## '.$heading."\n\n".$citation."\n".($s['url']??'')."\n\n".$text."\n\n".($entry['comment']??'')."\n\n";
  $escape=fn($t)=>htmlspecialchars($t,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$html.='<section><h2>'.$escape($heading).'</h2><p>'.$escape($citation).'</p><p>'.$escape($s['url']??'').'</p><pre>'.$escape($text).'</pre><pre>'.$escape($entry['comment']??'').'</pre></section>';
 }unset($entry);unset($d['revision'],$d['author']);
 $html='<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta http-equiv="Content-Security-Policy" content="default-src &apos;none&apos;; style-src &apos;unsafe-inline&apos;"><title>Dossier · Die ABLAGE</title><style>body{max-width:72ch;margin:3em auto;padding:0 1.2em;font:18px/1.7 Georgia;color:#202022}h1,h2{font-family:Arial,sans-serif}pre{white-space:pre-wrap;font:inherit;overflow-wrap:anywhere}section{border-top:1px solid #dededb;margin-top:2em;padding-top:1em}@media print{body{margin:0}h2{break-after:avoid}}</style>'.$html.'</html>';
 $path=tempnam(sys_get_temp_dir(),'ablage-dossier-');if(!$path)problem('Export konnte nicht vorbereitet werden.',503);$zip=new ZipArchive();try{if($zip->open($path,ZipArchive::OVERWRITE)!==true)problem('Export konnte nicht erstellt werden.',503);foreach($files as $name=>$file)$zip->addFile($file,$name);$zip->addFromString('dossier.md',$md);$zip->addFromString('dossier.html',$html);$zip->addFromString('dossier.json',json_encode($d,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$zip->addFromString('README.txt',"Nur ausgewählte Dossiereinträge. Keine privaten Clipnotizen, vollständigen Quell-PDFs, Leselinks oder Zugangsdaten. Ausdrücklich gewählte eigenständige Artikel-PDFs liegen ggf. unter artikel/. dossier.html lässt sich im Browser lesen und als PDF drucken.\n");$zip->close();header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="die-ablage-dossier.zip"');header('Content-Length: '.filesize($path));readfile($path);}finally{if(is_file($path))unlink($path);}exit;
}
